export function createCampusMotion(){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),seen=new WeakSet();let celebrationTimer;
 const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-revealed');observer.unobserve(entry.target)}},{threshold:.06}):null;
 function scan(root=document){if(reduced.matches||!observer)return;const selector='.topic-card,.experiment-card,.achievement-card,.campus-card',elements=[...(root.matches?.(selector)?[root]:[]),...(root.querySelectorAll?.(selector)||[])];for(const el of elements)if(!seen.has(el)){seen.add(el);el.classList.add('campus-reveal');observer.observe(el)}}
 new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1&&node.namespaceURI!=='http://www.w3.org/2000/svg'&&!node.closest?.('.interaction-bubbles,.vns-celebration'))scan(node)}).observe(document.querySelector('main'),{childList:true,subtree:true});scan();
 function feedback(el,correct){if(!el)return;el.classList.remove('answer-correct','answer-wrong');void el.offsetWidth;el.classList.add(correct?'answer-correct':'answer-wrong');if(!correct)setTimeout(()=>el.classList.remove('answer-wrong'),700)}
 function celebrate(badges){if(!badges.length)return;document.querySelector('.vns-celebration')?.remove();clearTimeout(celebrationTimer);const layer=document.createElement('div');layer.className='vns-celebration';const announcement=document.createElement('div');announcement.className='achievement-announcement';announcement.setAttribute('role','status');announcement.textContent=`✳ Thành tựu mới · ${badges.map(b=>b.name).join(' · ')}`;layer.append(announcement);if(!reduced.matches)for(let i=0;i<24;i++){const leaf=document.createElement('i');leaf.style.cssText=`--i:${i};--drift:${(i%2?1:-1)*(40+i*5)}px;--turn:${i*29}deg;--leaf-color:${['#bcd49a','#e4ce8d','#8fb7a3','#d4dda6'][i%4]}`;layer.append(leaf)}(document.querySelector('dialog[open]')||document.body).append(layer);celebrationTimer=setTimeout(()=>layer.remove(),4200)}
 return {feedback,celebrate,pageIn(page){if(!page)return;scan(page);if(!reduced.matches)page.animate([{opacity:.35,translate:'0 9px'},{opacity:1,translate:'0 0'}],{duration:260,easing:'cubic-bezier(.2,.7,.2,1)'})}};
}
